import{_ as r,o as d,c as o,ae as e}from"./chunks/framework.RRduUuAx.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-系统基础-计算机组成","description":"","frontmatter":{"title":"架构师-备考 综合知识-系统基础-计算机组成"},"headers":[],"relativePath":"综合知识/系统基础/计算机组成.md","filePath":"综合知识/系统基础/计算机组成.md"}'),n={name:"综合知识/系统基础/计算机组成.md"};function a(s,t,h,l,g,i){return d(),o("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 计算机硬件组成（5大部件/冯·诺依曼结构）</li><li>[x] CPU 组成（运算器 ALU+AC+DR+PSW / 控制器 IR+PC+AR+ID）</li><li>[x] CPU 功能与频率（主频=外频×倍频）</li><li>[x] 指令系统（组成/执行过程/寻址方式 / CISC vs RISC）</li><li>[x] Flynn 分类法（SISD/SIMD/MISD/MIMD）</li><li>[x] 指令流水线（周期/执行时间/吞吐率/加速比 / 超流水线/超标量/VLIW）</li><li>[x] 存储体系与分级存储（Cache/主存/辅存 / 局部性原理）</li><li>[x] Cache 地址映射（直接/全相联/组相联）+ 替换算法</li><li>[x] 磁盘结构与调度算法（FCFS/SSTF/SCAN/CSCAN）</li><li>[x] 总线结构（内部/系统/外部总线 / 数据+地址+控制总线）</li><li>[x] 校验码（奇偶校验/海明码/CRC）</li><li>[x] I/O 编址（独立编址 vs 统一编址）</li><li>[x] 数据交互方式（程序查询/中断/DMA）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、计算机硬件组成-★" tabindex="-1">一、计算机硬件组成 ★ <a class="header-anchor" href="#一、计算机硬件组成-★" aria-label="Permalink to &quot;一、计算机硬件组成 ★&quot;">​</a></h3><blockquote><p>计算机基本硬件系统由<strong>运算器、控制器、存储器、输入设备、输出设备</strong>5大部件组成。</p></blockquote><p>运算器 + 控制器 = <strong>CPU（中央处理单元）</strong>，是硬件系统核心。存储器分为内部（速度快容量小）和外部（容量大速度慢）。输入输出设备合称外设。</p><p><strong>冯·诺依曼结构</strong>：将计算机硬件划分为上述 5 部分。DSP 常采用<strong>哈佛体系结构</strong>（程序和数据分开存储）。</p><p><strong>专用处理器：</strong> GPU（数百/数千核并行计算）、DSP（实时数字信号处理）、FPGA（现场可编程门阵列）。</p><hr><h3 id="二、cpu-组成与功能-★" tabindex="-1">二、CPU 组成与功能 ★ <a class="header-anchor" href="#二、cpu-组成与功能-★" aria-label="Permalink to &quot;二、CPU 组成与功能 ★&quot;">​</a></h3><h4 id="运算器" tabindex="-1">运算器 <a class="header-anchor" href="#运算器" aria-label="Permalink to &quot;运算器&quot;">​</a></h4><table tabindex="0"><thead><tr><th>组件</th><th>功能</th></tr></thead><tbody><tr><td><strong>ALU</strong>（算术逻辑单元）</td><td>执行所有算术运算和逻辑运算</td></tr><tr><td><strong>AC</strong>（累加寄存器）</td><td>存放运算结果或源操作数</td></tr><tr><td><strong>DR</strong>（数据缓冲寄存器）</td><td>暂存来自内存的指令或数据</td></tr><tr><td><strong>PSW</strong>（状态条件寄存器）</td><td>保存指令执行后的条件码（进位/溢出/零标志等）</td></tr></tbody></table><h4 id="控制器" tabindex="-1">控制器 <a class="header-anchor" href="#控制器" aria-label="Permalink to &quot;控制器&quot;">​</a></h4><table tabindex="0"><thead><tr><th>组件</th><th>功能</th></tr></thead><tbody><tr><td><strong>IR</strong>（指令寄存器）</td><td>暂存 CPU 正在执行的指令</td></tr><tr><td><strong>PC</strong>（程序计数器）</td><td>存放<strong>下一条</strong>要执行指令的地址</td></tr><tr><td><strong>AR</strong>（地址寄存器）</td><td>保存 CPU 当前访问的内存地址</td></tr><tr><td><strong>ID</strong>（指令译码器）</td><td>分析指令操作码，识别操作类型</td></tr></tbody></table><p><strong>CPU 五大功能</strong>：程序控制、操作控制、时间控制、数据处理（最根本）、中断响应。</p><p><strong>CPU 频率</strong>：<strong>主频 = 外频 × 倍频</strong>。外频是系统总线频率，倍频是主频与外频的比值。</p><blockquote><p><strong>速度排名</strong>：寄存器组 &gt; Cache &gt; 内存 &gt; Flash。</p></blockquote><hr><h3 id="三、指令系统-★" tabindex="-1">三、指令系统 ★ <a class="header-anchor" href="#三、指令系统-★" aria-label="Permalink to &quot;三、指令系统 ★&quot;">​</a></h3><h4 id="指令组成与执行" tabindex="-1">指令组成与执行 <a class="header-anchor" href="#指令组成与执行" aria-label="Permalink to &quot;指令组成与执行&quot;">​</a></h4><blockquote><p>一条指令 = <strong>操作码</strong>（决定操作类型）+ <strong>地址码</strong>（操作数地址）。整条指令以二进制编码存放。</p></blockquote><p><strong>执行三阶段</strong>：取指令（PC→地址总线，从内存取）→ 分析指令（ID 解析操作码）→ 执行指令。</p><h4 id="寻址方式" tabindex="-1">寻址方式 <a class="header-anchor" href="#寻址方式" aria-label="Permalink to &quot;寻址方式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th>特点</th></tr></thead><tbody><tr><td><strong>顺序寻址</strong></td><td>一条接一条顺序执行</td><td>下一条地址由 PC 给出</td></tr><tr><td><strong>跳跃寻址</strong></td><td>下条地址由本条指令直接给出</td><td>PC 内容相应改变</td></tr></tbody></table><p><strong>操作数寻址方式：</strong></p><table tabindex="0"><thead><tr><th>方式</th><th>说明</th><th style="text-align:center;">速度</th></tr></thead><tbody><tr><td><strong>立即寻址</strong></td><td>地址码直接包含操作数本身</td><td style="text-align:center;">—</td></tr><tr><td><strong>直接寻址</strong></td><td>地址码是操作数的内存地址</td><td style="text-align:center;">—</td></tr><tr><td><strong>间接寻址</strong></td><td>地址码指向存有操作数地址的单元</td><td style="text-align:center;">慢</td></tr><tr><td><strong>寄存器寻址</strong></td><td>操作数在寄存器中</td><td style="text-align:center;"><strong>最快</strong></td></tr><tr><td><strong>基址寻址</strong></td><td>基址寄存器 + 形式地址 → 有效地址</td><td style="text-align:center;">用于静态数据</td></tr><tr><td><strong>变址寻址</strong></td><td>变址寄存器 + 形式地址 → 有效地址</td><td style="text-align:center;">用于数组/动态数据</td></tr></tbody></table><h4 id="cisc-vs-risc-★" tabindex="-1">CISC vs RISC ★ <a class="header-anchor" href="#cisc-vs-risc-★" aria-label="Permalink to &quot;CISC vs RISC ★&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对比</th><th>CISC（复杂指令集）</th><th>RISC（精简指令集）</th></tr></thead><tbody><tr><td>指令数量</td><td>多</td><td>少</td></tr><tr><td>指令长度</td><td><strong>可变</strong></td><td>固定</td></tr><tr><td>实现方式</td><td>微程序控制</td><td><strong>组合逻辑</strong>（硬件实现）</td></tr><tr><td>寻址方式</td><td>多样</td><td>少</td></tr><tr><td>寄存器</td><td>少</td><td><strong>大量寄存器</strong></td></tr><tr><td>执行时间</td><td>差别大</td><td>多数单周期</td></tr></tbody></table><hr><h3 id="四、flynn-分类法-★" tabindex="-1">四、Flynn 分类法 ★ <a class="header-anchor" href="#四、flynn-分类法-★" aria-label="Permalink to &quot;四、Flynn 分类法 ★&quot;">​</a></h3><blockquote><p>按<strong>指令流</strong>和<strong>数据流</strong>的多倍性将计算机分为 4 类。</p></blockquote><table tabindex="0"><thead><tr><th>分类</th><th>说明</th><th>典型代表</th></tr></thead><tbody><tr><td><strong>SISD</strong></td><td>单指令流单数据流</td><td>传统单处理器、冯·诺依曼机器</td></tr><tr><td><strong>SIMD</strong></td><td>单指令流多数据流</td><td>阵列处理机、并行处理机</td></tr><tr><td><strong>MISD</strong></td><td>多指令流单数据流</td><td><strong>极少见</strong>（有文献将流水线归为此类）</td></tr><tr><td><strong>MIMD</strong></td><td>多指令流多数据流</td><td>多核计算机、多处理机、超级计算机</td></tr></tbody></table><blockquote><p>当前主流多核计算机属于 <strong>MIMD</strong>。</p></blockquote><hr><h3 id="五、指令流水线-★" tabindex="-1">五、指令流水线 ★ <a class="header-anchor" href="#五、指令流水线-★" aria-label="Permalink to &quot;五、指令流水线 ★&quot;">​</a></h3><blockquote><p>将指令分成不同段，每段由不同部件并行处理。</p></blockquote><p><strong>RISC 流水线三种技术：</strong></p><table tabindex="0"><thead><tr><th>技术</th><th>核心理念</th><th>本质</th></tr></thead><tbody><tr><td><strong>超流水线</strong></td><td>细化流水、增加级数、提高主频</td><td><strong>时间换空间</strong></td></tr><tr><td><strong>超标量</strong></td><td>多条流水线同时执行多个处理</td><td><strong>空间换时间</strong></td></tr><tr><td><strong>超长指令字（VLIW）</strong></td><td>软件调度并行，简化硬件</td><td>软件发挥主要作用</td></tr></tbody></table><p><strong>流水线核心公式：</strong></p><table tabindex="0"><thead><tr><th>指标</th><th>公式</th></tr></thead><tbody><tr><td><strong>流水线周期</strong></td><td>各段中<strong>执行时间最长的段</strong>的时间</td></tr><tr><td><strong>执行时间</strong></td><td>1条指令总执行时间 +（总指令条数 - 1）× 流水线周期</td></tr><tr><td><strong>吞吐率</strong></td><td>指令条数 / 流水线执行时间</td></tr><tr><td><strong>加速比</strong></td><td>不使用流水线执行时间 / 使用流水线执行时间</td></tr></tbody></table><hr><h3 id="六、存储系统-★" tabindex="-1">六、存储系统 ★ <a class="header-anchor" href="#六、存储系统-★" aria-label="Permalink to &quot;六、存储系统 ★&quot;">​</a></h3><h4 id="分级存储" tabindex="-1">分级存储 <a class="header-anchor" href="#分级存储" aria-label="Permalink to &quot;分级存储&quot;">​</a></h4><blockquote><p>目的：解决存储<strong>容量、成本和速度</strong>之间的矛盾。按 CPU 物理距离分 4 层（由近→远）：片上缓存 → 片外缓存 → 主存（内存）→ 外存。速度依次降低，容量依次提高。</p></blockquote><p><strong>两级存储</strong>：Cache-主存、主存-辅存（虚拟存储体系）。</p><p><strong>局部性原理</strong>：</p><ul><li><strong>时间局部性</strong>：刚被访问的数据近期可能再次被访问</li><li><strong>空间局部性</strong>：相邻地址的数据可能被连续访问</li></ul><h4 id="cache-地址映射-★" tabindex="-1">Cache 地址映射 ★ <a class="header-anchor" href="#cache-地址映射-★" aria-label="Permalink to &quot;Cache 地址映射 ★&quot;">​</a></h4><blockquote><p>在 CPU 工作时，送出的是主存地址，需转换为 Cache 地址，称为<strong>地址映像</strong>，由<strong>硬件自动完成</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>映射方式</th><th>特点</th><th style="text-align:center;">块冲突概率</th></tr></thead><tbody><tr><td><strong>直接映像</strong></td><td>主存块与 Cache 块号相同才能命中，变换简单但不灵活</td><td style="text-align:center;"><strong>最高</strong></td></tr><tr><td><strong>全相联映像</strong></td><td>主存任意块可调入 Cache 任意块，变换复杂速度慢</td><td style="text-align:center;"><strong>最低</strong></td></tr><tr><td><strong>组相联映像</strong></td><td>组间直接映像 + 组内全相联映像，前两者折中</td><td style="text-align:center;">中</td></tr></tbody></table><blockquote><p>块冲突概率：<strong>直接映像 &gt; 组相联映像 &gt; 全相联映像</strong>。</p></blockquote><h4 id="替换算法" tabindex="-1">替换算法 <a class="header-anchor" href="#替换算法" aria-label="Permalink to &quot;替换算法&quot;">​</a></h4><table tabindex="0"><thead><tr><th>算法</th><th>说明</th></tr></thead><tbody><tr><td>随机替换</td><td>随机选择被替换块</td></tr><tr><td>先进先出（FIFO）</td><td>替换最先进入 Cache 的块</td></tr><tr><td><strong>近期最少使用（LRU）</strong></td><td>替换近期最少使用的块</td></tr><tr><td>优化替换</td><td>先执行一次程序统计替换情况，第二次用最优方式</td></tr></tbody></table><h4 id="命中率计算" tabindex="-1">命中率计算 <a class="header-anchor" href="#命中率计算" aria-label="Permalink to &quot;命中率计算&quot;">​</a></h4><blockquote><p>平均访问时间 = 命中率 × Cache 访问时间 +（1 - 命中率）× 主存访问时间。</p></blockquote><h4 id="磁盘结构与调度算法-★" tabindex="-1">磁盘结构与调度算法 ★ <a class="header-anchor" href="#磁盘结构与调度算法-★" aria-label="Permalink to &quot;磁盘结构与调度算法 ★&quot;">​</a></h4><p><strong>磁盘三大要素</strong>：磁头（Head）、柱面（Cylinder，所有盘面同位置磁道集合）、扇区（Sector，最小存储单元）。</p><table tabindex="0"><thead><tr><th>算法</th><th>说明</th><th>特点</th></tr></thead><tbody><tr><td><strong>FCFS</strong>（先来先服务）</td><td>按请求顺序调度</td><td>公平但效率低</td></tr><tr><td><strong>SSTF</strong>（最短寻道时间优先）</td><td>离当前磁道最近的请求优先</td><td>可能产生&quot;<strong>饥饿</strong>&quot;</td></tr><tr><td><strong>SCAN</strong>（扫描/电梯算法）</td><td>磁头双向移动到底才掉头</td><td>与电梯类似</td></tr><tr><td><strong>CSCAN</strong>（单向扫描）</td><td>只做单向移动</td><td>更均匀的等待时间</td></tr></tbody></table><hr><h3 id="七、总线结构-★" tabindex="-1">七、总线结构 ★ <a class="header-anchor" href="#七、总线结构-★" aria-label="Permalink to &quot;七、总线结构 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>作用域</th><th>关键特征</th></tr></thead><tbody><tr><td><strong>内部总线</strong>（片内）</td><td>芯片内部</td><td>高带宽、低延迟、不对外开放</td></tr><tr><td><strong>系统总线</strong>（板级）</td><td>主板+扩展槽</td><td>决定内存最大容量，三总线并行</td></tr><tr><td><strong>外部总线</strong>（设备级）</td><td>机箱外设</td><td>热插拔、即插即用</td></tr></tbody></table><p><strong>系统总线&quot;三驾马车&quot;：</strong></p><table tabindex="0"><thead><tr><th>总线</th><th style="text-align:center;">方向</th><th>作用</th></tr></thead><tbody><tr><td><strong>数据总线</strong></td><td style="text-align:center;">双向</td><td>传输数据，宽度 = 字长倍数</td></tr><tr><td><strong>地址总线</strong></td><td style="text-align:center;">单向</td><td>传输地址，宽度决定<strong>寻址空间</strong></td></tr><tr><td><strong>控制总线</strong></td><td style="text-align:center;">—</td><td>传输控制信号（读/写/中断/时钟等）</td></tr></tbody></table><hr><h3 id="八、校验码-★" tabindex="-1">八、校验码 ★ <a class="header-anchor" href="#八、校验码-★" aria-label="Permalink to &quot;八、校验码 ★&quot;">​</a></h3><blockquote><p><strong>码距</strong>：两个编码之间至少需要改变的位数。码距越大，检错纠错能力越强。</p></blockquote><table tabindex="0"><thead><tr><th>校验码</th><th style="text-align:center;">能力</th><th>关键特性</th></tr></thead><tbody><tr><td><strong>奇偶校验</strong></td><td style="text-align:center;">检错（仅奇数位）</td><td>增加 1 位校验位使 1 的个数为奇/偶，码距=2，<strong>不能纠错</strong></td></tr><tr><td><strong>海明码</strong></td><td style="text-align:center;">检错 + <strong>纠错</strong>（1位）</td><td>校验位在 2 的幂次方位置（1,2,4,8...），公式 <strong>2^k ≥ n+k+1</strong></td></tr><tr><td><strong>CRC</strong></td><td style="text-align:center;">检错</td><td>模 2 除法（异或），只能检错<strong>不能纠错</strong>，约定生成多项式 G(x)</td></tr></tbody></table><p><strong>海明码解题流程</strong>：确定校验位数量 k（2^k ≥ n+k+1）→ 校验位放 2 的幂次方位置 → 按位负责关系计算各校验位（偶校验）→ 写出编码。</p><p><strong>CRC 解题流程</strong>：原始信息后补 r 个 0（r = G(x) 最高次）→ G(x) 转二进制除数 → 模 2 除法得余数 → 拼接发送。</p><hr><h3 id="九、输入-输出技术-★" tabindex="-1">九、输入/输出技术 ★ <a class="header-anchor" href="#九、输入-输出技术-★" aria-label="Permalink to &quot;九、输入/输出技术 ★&quot;">​</a></h3><h4 id="i-o-编址方式" tabindex="-1">I/O 编址方式 <a class="header-anchor" href="#i-o-编址方式" aria-label="Permalink to &quot;I/O 编址方式&quot;">​</a></h4><table tabindex="0"><thead><tr><th>对比</th><th>独立编址（I/O 映射）</th><th>统一编址（内存映射）</th></tr></thead><tbody><tr><td>地址空间</td><td>内存+I/O 两个独立空间</td><td>统一地址空间</td></tr><tr><td>指令</td><td>专用 I/O 指令（IN/OUT）</td><td>通用内存访问指令</td></tr><tr><td>优点</td><td>易辨认、互不干扰</td><td>指令丰富灵活</td></tr><tr><td>缺点</td><td>指令功能有限</td><td>内存地址不连续</td></tr><tr><td>典型</td><td>Intel x86</td><td>ARM、嵌入式</td></tr></tbody></table><h4 id="数据交互三种方式-★" tabindex="-1">数据交互三种方式 ★ <a class="header-anchor" href="#数据交互三种方式-★" aria-label="Permalink to &quot;数据交互三种方式 ★&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方式</th><th style="text-align:center;">CPU 参与度</th><th style="text-align:center;">效率</th><th>机制</th></tr></thead><tbody><tr><td><strong>程序查询</strong></td><td style="text-align:center;">全程参与</td><td style="text-align:center;">最低</td><td>CPU 主动轮询设备状态</td></tr><tr><td><strong>程序中断</strong></td><td style="text-align:center;">传输后处理</td><td style="text-align:center;">中</td><td>设备就绪后<strong>主动通知</strong>CPU</td></tr><tr><td><strong>DMA</strong></td><td style="text-align:center;">仅初始化</td><td style="text-align:center;"><strong>最高</strong></td><td>DMA 控制器接管总线，直接设备↔内存</td></tr></tbody></table><p><strong>中断 vs DMA 响应时机：</strong></p><ul><li>CPU 响应<strong>中断</strong>请求：在<strong>一条指令执行结束时</strong></li><li>CPU 响应<strong>DMA</strong>请求：在一个<strong>总线周期结束后</strong></li></ul><blockquote><p>DMA 方式数据传输整个过程由 DMA 控制器完成，<strong>不需要 CPU 执行程序指令来传送数据</strong>。</p></blockquote>',78)])])}const u=r(n,[["render",a]]);export{c as __pageData,u as default};
